helpers.log('Starting Filter & Sort node');

const operation = node.properties.operation.value;
let inputArray = node.properties.inputArray.value;
let filterConditions = node.properties.filterConditions?.value || [];
let sortFields = node.properties.sortFields?.value || [];
const uniqueField = node.properties.uniqueField?.value;
const limitCount = node.properties.limitCount?.value || 10;
const limitOffset = node.properties.limitOffset?.value || 0;

helpers.log(`Operation: ${operation}`);

// Resolve template variables
const resolveValue = (val) => {
  if (typeof val === 'string') {
    if (val === '{{data}}') return data;
    if (val.includes('{{data.')) {
      const match = val.match(/\{\{data\.([^}]+)\}\}/);
      if (match) {
        const path = match[1].split('.');
        let result = data;
        for (const part of path) {
          result = result?.[part];
        }
        return result;
      }
    }
  }
  return val;
};

inputArray = resolveValue(inputArray);

// Ensure it's an array
if (!Array.isArray(inputArray)) {
  helpers.error('Input is not an array');
  return {
    error: 'Input is not an array',
    receivedType: typeof inputArray
  };
}

helpers.log(`Input array length: ${inputArray.length}`);

// Helper to get nested value
const getNestedValue = (obj, path) => {
  if (!path) return obj;
  const keys = path.split('.');
  let result = obj;
  for (const key of keys) {
    if (result === null || result === undefined) return undefined;
    result = result[key];
  }
  return result;
};

// Helper to compare values
const compareValues = (a, b, operator) => {
  switch (operator) {
    case 'equals':
      return a == b;
    case 'notEquals':
      return a != b;
    case 'greaterThan':
      return a > b;
    case 'lessThan':
      return a < b;
    case 'greaterThanOrEqual':
      return a >= b;
    case 'lessThanOrEqual':
      return a <= b;
    case 'contains':
      return String(a).includes(String(b));
    case 'startsWith':
      return String(a).startsWith(String(b));
    case 'endsWith':
      return String(a).endsWith(String(b));
    case 'in':
      return Array.isArray(b) ? b.includes(a) : false;
    case 'exists':
      return a !== undefined && a !== null;
    case 'empty':
      return !a || (Array.isArray(a) && a.length === 0) || (typeof a === 'string' && a.trim() === '');
    default:
      return false;
  }
};

try {
  let result;

  switch (operation) {
    case 'filter': {
      if (!Array.isArray(filterConditions) || filterConditions.length === 0) {
        helpers.warn('No filter conditions defined, returning all items');
        return {
          success: true,
          operation: 'filter',
          result: inputArray,
          originalCount: inputArray.length,
          filteredCount: inputArray.length,
          conditions: []
        };
      }

      helpers.log(`Filtering with ${filterConditions.length} condition(s) (AND logic)`);

      result = inputArray.filter(item => {
        // All conditions must match (AND logic)
        return filterConditions.every((condition, idx) => {
          const fieldValue = getNestedValue(item, condition.field);
          const conditionValue = resolveValue(condition.value);
          const matches = compareValues(fieldValue, conditionValue, condition.operator);

          if (idx === 0) {
            helpers.log(`Condition ${idx + 1}: ${condition.field} ${condition.operator} ${JSON.stringify(conditionValue)}`);
          }

          return matches;
        });
      });

      helpers.log(`Filtered ${inputArray.length} items down to ${result.length} items`);

      return {
        success: true,
        operation: 'filter',
        result,
        originalCount: inputArray.length,
        filteredCount: result.length,
        conditions: filterConditions
      };
    }

    case 'find': {
      if (!Array.isArray(filterConditions) || filterConditions.length === 0) {
        helpers.warn('No filter conditions defined, returning first item');
        return {
          success: true,
          operation: 'find',
          result: inputArray[0] || null,
          found: inputArray.length > 0,
          conditions: []
        };
      }

      helpers.log(`Finding first item matching ${filterConditions.length} condition(s)`);

      result = inputArray.find(item => {
        return filterConditions.every(condition => {
          const fieldValue = getNestedValue(item, condition.field);
          const conditionValue = resolveValue(condition.value);
          return compareValues(fieldValue, conditionValue, condition.operator);
        });
      });

      if (result) {
        helpers.log('Found matching item');
      } else {
        helpers.log('No matching item found');
      }

      return {
        success: true,
        operation: 'find',
        result: result || null,
        found: !!result,
        conditions: filterConditions
      };
    }

    case 'sort': {
      if (!Array.isArray(sortFields) || sortFields.length === 0) {
        helpers.warn('No sort fields defined, returning items in original order');
        return {
          success: true,
          operation: 'sort',
          result: inputArray,
          count: inputArray.length,
          sortFields: []
        };
      }

      helpers.log(`Sorting by ${sortFields.length} field(s)`);
      sortFields.forEach((sf, idx) => {
        helpers.log(`Sort ${idx + 1}: ${sf.field} (${sf.direction})`);
      });

      result = [...inputArray].sort((a, b) => {
        // Multi-field sorting: iterate through sort fields until we find a difference
        for (const sortField of sortFields) {
          const aVal = getNestedValue(a, sortField.field);
          const bVal = getNestedValue(b, sortField.field);

          // Handle null/undefined
          if (aVal === null || aVal === undefined) {
            if (bVal === null || bVal === undefined) continue;
            return 1;
          }
          if (bVal === null || bVal === undefined) return -1;

          // Compare
          let comparison = 0;
          if (aVal > bVal) comparison = 1;
          if (aVal < bVal) comparison = -1;

          if (comparison !== 0) {
            return sortField.direction === 'desc' ? -comparison : comparison;
          }
        }
        return 0;
      });

      helpers.log(`Sorted ${result.length} items`);

      return {
        success: true,
        operation: 'sort',
        result,
        count: result.length,
        sortFields
      };
    }

    case 'unique': {
      if (uniqueField) {
        helpers.log(`Removing duplicates by field: ${uniqueField}`);
        const seen = new Set();
        result = inputArray.filter(item => {
          const value = getNestedValue(item, uniqueField);
          const key = JSON.stringify(value);
          if (seen.has(key)) return false;
          seen.add(key);
          return true;
        });
      } else {
        helpers.log('Removing duplicates by full object comparison');
        const seen = new Set();
        result = inputArray.filter(item => {
          const key = JSON.stringify(item);
          if (seen.has(key)) return false;
          seen.add(key);
          return true;
        });
      }

      helpers.log(`Removed ${inputArray.length - result.length} duplicates (${result.length} unique items remaining)`);

      return {
        success: true,
        operation: 'unique',
        result,
        originalCount: inputArray.length,
        uniqueCount: result.length,
        duplicatesRemoved: inputArray.length - result.length,
        uniqueField
      };
    }

    case 'limit': {
      helpers.log(`Limiting results: offset=${limitOffset}, count=${limitCount}`);
      result = inputArray.slice(limitOffset, limitOffset + limitCount);
      helpers.log(`Returned ${result.length} items from ${inputArray.length} total`);

      return {
        success: true,
        operation: 'limit',
        result,
        originalCount: inputArray.length,
        returnedCount: result.length,
        limit: limitCount,
        offset: limitOffset
      };
    }

    default:
      helpers.error(`Unknown operation: ${operation}`);
      return { error: `Unknown operation: ${operation}` };
  }
} catch (error) {
  helpers.error('Filter/Sort operation failed:', error.message);
  return {
    error: error.message,
    operation
  };
}
